import time

from taf.fdsw.rc.clients.exceptions import ClientRequestFailed
from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.interfaces.FDSW21A.autoconnection import AutoConfiguration21A


class AutoConfiguration21C(AutoConfiguration21A):

    def __init__(self, client):
        super(AutoConfiguration21C, self).__init__(client)

    def set_autoconnection_parameters_to_default(self, *args, **kwargs):
        parameters = {"scenario": "private network with DHCP"}
        try:

            self._client.send(
                method='config.autoconnection.update',
                timeout=30,
                parameters=parameters)
        except ClientRequestFailed:
            time.sleep(4)
            autoconnection_parameters = self.get_autoconnection_parameters()
            if not self.is_subset(parameters, autoconnection_parameters):
                raise OperationFailure('Paramertes have not been set to default succesfully')
